{
  "opening": "This release introduces several new locale support options and enhances the robustness of date parsing and humanization features. It also expands input flexibility for the main factory class to accommodate decimal values.",
  "requirements": [
    {
      "id": "m03",
      "text": "The library must provide a ZuluLocale class that is accessible alongside existing locale classes like LuxembourgishLocale."
    },
    {
      "id": "m04",
      "text": "The library must provide a TamilLocale class that is accessible alongside existing locale classes like ZuluLocale."
    },
    {
      "id": "m06",
      "text": "The DateTimeParser must enforce stricter validation when processing tokens 'A' and 'hh', raising appropriate errors for invalid inputs."
    },
    {
      "id": "m14",
      "text": "The MoroccoArabicLocale must correctly implement dehumanization functionality, ensuring consistent output formats for relative time strings."
    },
    {
      "id": "m15",
      "text": "The library must provide an AlbanianLocale class that is accessible alongside existing locale classes like TamilLocale."
    },
    {
      "id": "m20",
      "text": "The FinnishLocale must support the dehumanize method, returning accurate relative time strings in the Finnish language."
    },
    {
      "id": "m21",
      "text": "The ArrowFactory must accept Decimal instances as input arguments, treating them equivalently to float or int values for date creation."
    }
  ],
  "closing": "Please ensure all new locales are properly registered and that the parser improvements do not regress existing valid use cases."
}
